//! 📖️ Indexed AP214 draughting appearances and positioned text in typographic points.
use semio_s_artifact_stdio_contract::part21::{Part21Document,Part21Instance,Part21Value};
use super::super::projection::{ProjectionGraph,placement,length_unit};
#[derive(Clone,Debug,PartialEq)]
pub struct CurvePaint{pub source_id:u64,pub fill:Option<[f64;3]>,pub stroke:Option<[f64;3]>,pub stroke_width:Option<f64>}
#[derive(Clone,Debug,PartialEq)]
pub struct TextAnnotation{pub source_id:u64,pub name:String,pub literal:String,pub position:[f64;3],pub x_axis:[f64;3],pub y_axis:[f64;3],pub width:f64,pub height:f64,pub font_size:f64,pub color:Option<[f64;3]>}
#[derive(Clone,Debug,PartialEq)]
pub struct DraughtingProjection{pub texts:Vec<TextAnnotation>,pub paints:Vec<CurvePaint>,pub unit_to_points:f64,pub issues:Vec<String>}
fn reference(value:Option<&Part21Value>)->Option<u64>{value.and_then(Part21Value::as_ref_id)}
fn refs(value:Option<&Part21Value>)->impl Iterator<Item=u64>+'_ {value.and_then(Part21Value::as_list).into_iter().flatten().filter_map(Part21Value::as_ref_id)}
fn args<'a>(graph:&ProjectionGraph<'a>,id:u64,kind:&str)->Option<&'a[Part21Value]>{graph.instance(id)?.entity(kind).map(Vec::as_slice)}
fn color(graph:&ProjectionGraph<'_>,id:u64)->Option<[f64;3]>{let instance=graph.instance(id)?;if let Some(values)=instance.entity("COLOUR_RGB"){let rgb=[values.get(1)?.as_real()?,values.get(2)?.as_real()?,values.get(3)?.as_real()?];return rgb.into_iter().all(|value|value.is_finite()&&(0.0..=1.0).contains(&value)).then_some(rgb);}let name=instance.entity("DRAUGHTING_PRE_DEFINED_COLOUR")?.first()?.as_str()?;match name{"black"=>Some([0.0,0.0,0.0]),"white"=>Some([1.0,1.0,1.0]),"red"=>Some([1.0,0.0,0.0]),"green"=>Some([0.0,1.0,0.0]),"blue"=>Some([0.0,0.0,1.0]),"yellow"=>Some([1.0,1.0,0.0]),"magenta"=>Some([1.0,0.0,1.0]),"cyan"=>Some([0.0,1.0,1.0]),_=>None}}
fn measure(value:&Part21Value)->Option<f64>{match value{Part21Value::Typed{items,..}=>items.first()?.as_real(),_=>value.as_real()}.filter(|value|value.is_finite()&&*value>0.0)}
fn styles<'a>(graph:&ProjectionGraph<'a>,instance:&'a Part21Instance)->Vec<&'a Part21Instance>{let Some((_,values))=instance.entities.iter().find(|(kind,_)|matches!(kind.as_str(),"STYLED_ITEM"|"ANNOTATION_FILL_AREA_OCCURRENCE"|"ANNOTATION_TEXT_OCCURRENCE"))else{return Vec::new()};refs(values.get(1)).filter_map(|id|args(graph,id,"PRESENTATION_STYLE_ASSIGNMENT")).flat_map(|values|refs(values.first())).filter_map(|id|graph.instance(id)).collect()}
/// 🖌️ Reads standard RGB curve/fill/text appearances and explicit annotation placement without font or CAD dependencies.
pub fn read_draughting(doc:&Part21Document)->Result<DraughtingProjection,String>{
    let graph=ProjectionGraph::new(doc);let unit=length_unit(&graph)?;let mut output=DraughtingProjection{texts:Vec::new(),paints:Vec::new(),unit_to_points:unit,issues:Vec::new()};let mut paints=std::collections::BTreeMap::new();let mut text_styles=std::collections::HashMap::new();
    for instance in &doc.instances{let mut target=None;let mut fill=false;if let Some(values)=instance.entity("STYLED_ITEM"){target=reference(values.get(2));}else if let Some(values)=instance.entity("ANNOTATION_FILL_AREA_OCCURRENCE"){fill=true;target=reference(values.get(2)).and_then(|id|args(&graph,id,"ANNOTATION_FILL_AREA")).and_then(|values|{let mut ids=refs(values.get(1));let first=ids.next();if ids.next().is_some(){None}else{first}});if target.is_none(){output.issues.push(format!("#{}: step.draughting.fill-boundaries",instance.id));}}else if let Some(values)=instance.entity("ANNOTATION_TEXT_OCCURRENCE"){if let Some(id)=reference(values.get(2)){text_styles.insert(id,instance);}}
        if let Some(id)=target{let paint=paints.entry(id).or_insert(CurvePaint{source_id:id,fill:None,stroke:None,stroke_width:None});for style in styles(&graph,instance){if !fill{if let Some(values)=style.entity("CURVE_STYLE"){paint.stroke=reference(values.get(3)).and_then(|id|color(&graph,id));paint.stroke_width=values.get(2).and_then(measure).map(|value|value*unit);if paint.stroke.is_none()||paint.stroke_width.is_none(){output.issues.push(format!("#{}: step.draughting.curve-style",instance.id));}}}else if let Some(values)=style.entity("FILL_AREA_STYLE"){for style in refs(values.get(1)){paint.fill=args(&graph,style,"FILL_AREA_STYLE_COLOUR").and_then(|values|reference(values.get(1))).and_then(|id|color(&graph,id)).or(paint.fill);}if paint.fill.is_none(){output.issues.push(format!("#{}: step.draughting.fill-style",instance.id));}}}if paints.len()>16384{return Err("step.draughting.item-limit".into());}}
    }
    for instance in graph.by_type("TEXT_LITERAL_WITH_EXTENT"){if output.texts.len()>=16384{return Err("step.draughting.item-limit".into());}let read=||->Option<TextAnnotation>{let values=instance.entity("TEXT_LITERAL_WITH_EXTENT")?;let literal=values.get(1)?.as_str()?;if literal.len()>8*1024*1024{return None;}if values.get(3)?.as_str()? != "bottom left"||!matches!(values.get(4),Some(Part21Value::Enum(path))if path=="RIGHT"){return None;}let(position,x_axis,y_axis)=placement(&graph,reference(values.get(2))?)?;if x_axis[2].abs()>1e-9||y_axis[2].abs()>1e-9||x_axis[0]*y_axis[1]-x_axis[1]*y_axis[0]<0.999999{return None;}let extent=args(&graph,reference(values.get(6))?,"PLANAR_EXTENT")?;let width=measure(extent.get(1)?)?*unit;let height=measure(extent.get(2)?)?*unit;let mut annotation=TextAnnotation{source_id:instance.id,name:values.first()?.as_str()?.into(),literal:literal.into(),position:position.map(|value|value*unit),x_axis,y_axis,width,height,font_size:height,color:None};if let Some(occurrence)=text_styles.get(&instance.id){for style in styles(&graph,occurrence){if let Some(values)=style.entity("TEXT_STYLE_WITH_BOX_CHARACTERISTICS").or_else(||style.entity("TEXT_STYLE")){annotation.color=reference(values.get(1)).and_then(|id|args(&graph,id,"TEXT_STYLE_FOR_DEFINED_FONT")).and_then(|values|reference(values.first())).and_then(|id|color(&graph,id));if let Some(boxes)=values.get(2).and_then(Part21Value::as_list){for value in boxes{if matches!(value,Part21Value::Typed{name,..}if name=="BOX_HEIGHT"){annotation.font_size=measure(value)?*unit;}}}}}}annotation.position.into_iter().all(f64::is_finite).then_some(annotation)};match read(){Some(text)=>output.texts.push(text),None=>output.issues.push(format!("#{}: step.draughting.text-placement-style",instance.id))}}
    for instance in graph.by_type("TEXT_LITERAL"){if instance.entity("TEXT_LITERAL_WITH_EXTENT").is_none(){output.issues.push(format!("#{}: step.draughting.text-extent-required",instance.id));}}output.paints=paints.into_values().collect();Ok(output)
}
